  foreach($repo in @($src,$planning)){New-Item -ItemType Directory $repo -Force|Out-Null;Invoke-FixtureGit $repo @('init','-q');Invoke-FixtureGit $repo @('config','user.email','fixture@example.invalid');Invoke-FixtureGit $repo @('config','user.name','Fixture');Invoke-FixtureGit $repo @('config','core.autocrlf','false');Invoke-FixtureGit $repo @('checkout','-q','-b','main');[IO.File]::WriteAllText((Join-Path $repo 'base.txt'),"base`n");Invoke-FixtureGit $repo @('add','.');Invoke-FixtureGit $repo @('commit','-q','-m','base')}
