  $planOld=Invoke-FixtureGit $planning @('rev-parse','HEAD');New-Item -ItemType Directory $ws -Force|Out-Null;[IO.File]::WriteAllText((Join-Path $ws 'prepared.txt'),"prepared`n");Invoke-FixtureGit $planning @('add','.');Invoke-FixtureGit $planning @('commit','-q','-m','prepare');$prepared=Invoke-FixtureGit $planning @('rev-parse','HEAD')
  New-Item -ItemType Directory (Join-Path $ws 'receipts') -Force|Out-Null;Write-Json (Join-Path $ws 'unit-status.json') ([ordered]@{unit_id='trigger-unit';status='accepted'});Write-Json (Join-Path $ws 'prepared-event.json') ([ordered]@{event_id='trigger-unit-push-prepared-0001';event_type='commit'})
  $plan=[ordered]@{schema='rusty.morphospace.workflow.push_bundle_plan.v1';bundle_id='trigger-unit-push-bundle';project_id='test-project';unit_ids=@('trigger-unit');prepared_at='2026-07-20T10:00:00Z';dependency_order=@('source-repo','planning-repo');repositories=@([ordered]@{repo_id='source-repo';role='source';branch='main';commit=$srcFinal;upstream='origin/main';ahead=0;behind=0},[ordered]@{repo_id='planning-repo';role='planning';branch='main';commit=$prepared;upstream='origin/main';ahead=0;behind=0});source_first=$true;planning_last=$true;execution='not-performed';force_push_allowed=$false};Write-Json (Join-Path $ws 'receipts\plan.json') $plan
