  $executedRel='project/morphospace/receipts/executed.json';$accountRel='project/morphospace/receipts/accounting.json';Invoke-FixtureGit $planning @('add',$executedRel,$accountRel);Invoke-FixtureGit $planning @('commit','-q','-m','publish exact prerequisites');$suffix=Invoke-FixtureGit $planning @('rev-parse','HEAD');$suffixTree=Invoke-FixtureGit $planning @('rev-parse','HEAD^{tree}');$preparedTree=Invoke-FixtureGit $planning @('rev-parse',"$prepared^{tree}")
  Invoke-FixtureGit $src @('update-ref','refs/remotes/origin/main',$srcFinal);Invoke-FixtureGit $planning @('update-ref','refs/remotes/origin/main',$suffix)
