  $spec=[pscustomobject]@{project_id='test-project'};$state=[pscustomobject]@{current_unit=$null;pending_push_bundle=[pscustomobject]@{bundle_id=$plan.bundle_id;unit_ids=@('trigger-unit');repo_ids=@('source-repo','planning-repo')}};$map=@{'source-repo'=[pscustomobject]@{path=$src};'planning-repo'=[pscustomobject]@{path=$planning}};$sourceState=[pscustomobject]@{repo_id='source-repo';dirty=$false;diverged=$false;ahead=0;behind=0;head=$srcFinal;branch='main';upstream='origin/main'};$planningState=[pscustomobject]@{repo_id='planning-repo';dirty=$false;diverged=$false;ahead=0;behind=0;head=$suffix;branch='main';upstream='origin/main'}
  Test-MorphospacePublishedPrerequisiteSuffixLive $docPath $ws $spec $state $map @($sourceState,$planningState)|Out-Null
  $cases=@('extra-path','extra-commit','bad-accounting-hash','bad-executed-hash','dirty','ahead','behind','diverged','nonancestor','alternate-history','source-drift','force','rewrite','wrong-unit','wrong-bundle','missing-receipt','missing-object','repeated-consumption')
  foreach($case in $cases){$bad=Clone $doc;$badState=Clone $state;$badSource=Clone $sourceState;$badPlanning=Clone $planningState;switch($case){'extra-path'{$bad.publication.changed_paths[0]='extra.json'}'extra-commit'{$bad.publication.commit_count=2}'bad-accounting-hash'{$bad.planned_publication_accounting.sha256=('0'*64)}'bad-executed-hash'{$bad.planning_repository.executed_push_receipt.sha256=('0'*64)}'dirty'{$badPlanning.dirty=$true}'ahead'{$badPlanning.ahead=1}'behind'{$badPlanning.behind=1}'diverged'{$badPlanning.diverged=$true}'nonancestor'{$bad.planning_repository.published_suffix_parent=$srcOld}'alternate-history'{$bad.planning_repository.execution_final_revision=$srcOld;$bad.planning_repository.published_suffix_parent=$srcOld}'source-drift'{$bad.source_repositories[0].current_remote_readback_revision=$srcOld}'force'{$bad.publication.force_push_used=$true}'rewrite'{$bad.publication.rewrite_used=$true}'wrong-unit'{$bad.trigger_unit_id='wrong-unit'}'wrong-bundle'{$bad.bundle_id='wrong-bundle'}'missing-receipt'{$bad.planned_publication_accounting.path='receipts/missing.json'}'missing-object'{$bad.planning_repository.published_suffix_revision=('f'*40);$bad.planning_repository.current_remote_readback_revision=('f'*40)}'repeated-consumption'{$badState.pending_push_bundle=$null}};$badPath=Join-Path $ws "receipts\bad-$case.json";Write-Json $badPath $bad;Reject {Test-MorphospacePublishedPrerequisiteSuffixLive $badPath $ws $spec $badState $map @($badSource,$badPlanning)} $case}
